/** Actual same-query compositions of the shared physical, Province, monthly writer and assault kernels. */
public final class ArmyStrengthsRefillComposition {
    private ArmyStrengthsRefillComposition() { }
    public record LandPost(int armyId,Integer nativeCarmyId,Coverage status,ProvinceUsageProjection.Result usage,LandContextRow context,FullLandRateProjection fullRate){
        public boolean ready(){return fullRate!=null&&fullRate.ready();}public Long rate(){return fullRate!=null&&fullRate.numericResult() instanceof LandStockModel.AvailableRate value?value.conditionalRate():null;}
    }
    public record LandRates(List<LandPost> rows){public LandRates{rows=List.copyOf(rows);}}
    public enum SupplyMode {LAND,FLEET,UNKNOWN}
    public record RateSelection(SupplyMode mode,boolean ready,Long raw,String basis,String branchSource,List<String> missing){public RateSelection{missing=List.copyOf(missing);}}
    public record RegimentGap(int armyRegimentId,List<String> inputs){public RegimentGap{inputs=List.copyOf(inputs);}}
    public record SelectedUnion(AssociatedRefillProjection.Result projection,Map<Integer,FullDataModel.Snapshot> selected,List<RegimentGap> missing){public SelectedUnion{selected=java.util.Collections.unmodifiableMap(new LinkedHashMap<>(selected));missing=List.copyOf(missing);}}
    public record DerivedStrength(ArmyStrengths.Regiment source,Integer current,Integer maximum) { }
    public record DerivedRecord(FullDataModel.DataRecord source,FullDataModel.RecordStatus status,String unavailableReason,Integer current,Integer maximum,Integer effective) { }
    public record DerivedData(FullDataModel.Snapshot source,FullDataModel.Coverage status,String unavailableReason,List<DerivedRecord> records){public DerivedData{records=List.copyOf(records);}}
    public record NativeCount(int flags,boolean ready,Integer count) { }
    public record SubjectFrame(boolean currentMaximumReady,List<DerivedStrength> regiments,List<DerivedData> data,List<NativeCount> counts,List<RegimentGap> missing){public SubjectFrame{regiments=List.copyOf(regiments);data=List.copyOf(data);counts=List.copyOf(counts);missing=List.copyOf(missing);}}
    public record MonthlyOutcome(MonthlyLossModel.Result budgets,LossSequenceModel.Result sequence,ArmyMonthlyCaller.Result caller) { }
    public record SelectedMonthly(ArmyStrengths.Row source,Coverage status,boolean ready,SelectedUnion union,SubjectFrame subject,LandPost land,RateSelection rate,MonthlyOutcome monthly,boolean rateRequired) { }
    public record MonthlyAssemblies(List<SelectedMonthly> rows){public MonthlyAssemblies{rows=List.copyOf(rows);}}
    public static void install(ArmyStrengthsPipeline pipeline,ExactRef source){
        pipeline.register(Stage.SAME_INPUT_CONDITIONAL_POST_REFILL_LAND_SUPPLY_RATE_V1,LandRates.class,List.of(),(input,earlier)->new LandRates(input.selected().stream().map(row->postLand(row,earlier.rowJson(row))).toList()),value->encodeRows(value.rows(),ArmyStrengthsRefillComposition::encodeLand),value->publicStages(Stage.SAME_INPUT_CONDITIONAL_POST_REFILL_LAND_SUPPLY_RATE_V1,encodeRows(value.rows(),ArmyStrengthsRefillComposition::encodeLand)),source);
        pipeline.register(Stage.SAME_INPUT_CONDITIONAL_SELECTED_REFILL_MONTHLY_ASSEMBLY_V1,MonthlyAssemblies.class,List.of(Stage.SAME_INPUT_CONDITIONAL_POST_REFILL_LAND_SUPPLY_RATE_V1),(input,earlier)->{
            List<LandPost> land=earlier.required(Stage.SAME_INPUT_CONDITIONAL_POST_REFILL_LAND_SUPPLY_RATE_V1,LandRates.class).rows();List<SelectedMonthly> result=new ArrayList<>();for(int index=0;index<input.selected().size();index++){var row=input.selected().get(index);require(land.get(index).armyId()==row.core().army().value(),"same-row land projection order differs");result.add(selectedMonthly(row,earlier.rowJson(row),land.get(index)));}return new MonthlyAssemblies(result);
        },value->encodeRows(value.rows(),ArmyStrengthsRefillComposition::encodeMonthly),value->publicStages(Stage.SAME_INPUT_CONDITIONAL_SELECTED_REFILL_MONTHLY_ASSEMBLY_V1,encodeRows(value.rows(),ArmyStrengthsRefillComposition::encodeMonthly)),source);
        ArmyStrengthsRefillBesieging.install(pipeline,source);
    }
    public static LandPost postLand(ArmyStrengths.Row row,JsonNode nativeRow){
        ProvinceUsageProjection.Result usage=ProvinceUsageProjection.project(nativeRow);LandContextRow context=LandContextCodec.decodeRow(nativeRow);FullLandRateProjection full=usage.conditionalReady()?FullLandRatePolicy.project(context,usage.conditionalUsage()):null;
        boolean ready=full!=null&&full.ready(),any=usage.conditionalReady()||usage.currentSumReady()||context.currentObservedTotalRateRaw()!=null||context.resupply()!=null&&context.resupply().currentObservationReady()||context.rateInputs()!=null&&context.rateInputs().currentObservationReady();
        return new LandPost(row.core().army().value(),nativeId(row),ready?Coverage.AVAILABLE:any?Coverage.PARTIAL:Coverage.UNAVAILABLE,usage,context,full);
    }
    public static SelectedUnion selectedUnion(ArmyStrengths.Row row,LandContextRow land){
        Map<Integer,List<FullDataModel.Snapshot>> candidates=new LinkedHashMap<>();FullDataRecords own=source(row,FullDataRecords.class,ArmyStrengthsFamilies.Key.REGIMENT_REPLENISHMENT_RECORDS_V1);
        if(own!=null)own.values().forEach(data->candidates.computeIfAbsent(data.armyRegimentId(),ignored->new ArrayList<>()).add(data));
        if(land.province()!=null)for(var occurrence:land.province().occurrences())if(Boolean.TRUE.equals(occurrence.included()))for(var regiment:occurrence.regiments())if(Boolean.TRUE.equals(regiment.nativeSupplyLossEligible())&&regiment.replenishmentRecords()!=null)candidates.computeIfAbsent(regiment.armyRegimentId(),ignored->new ArrayList<>()).add(regiment.replenishmentRecords());
        Map<Integer,FullDataModel.Snapshot> selected=new LinkedHashMap<>();List<RegimentGap> missing=new ArrayList<>();for(var entry:candidates.entrySet()){
            List<FullDataModel.Snapshot> complete=entry.getValue().stream().filter(data->data.status()==FullDataModel.Coverage.AVAILABLE).toList();FullDataModel.Snapshot chosen=complete.isEmpty()?entry.getValue().getFirst():complete.getFirst();
            if(complete.stream().skip(1).anyMatch(data->!data.equals(chosen))){missing.add(new RegimentGap(entry.getKey(),List.of("consistent_same_physical_ArRg_DATA")));continue;}selected.put(entry.getKey(),chosen);
        }
        var union=AssociatedRefillProjection.project(new AssociatedRefillProjection.Input(true,row.core().army().value(),new ArrayList<>(selected.values()),selected.keySet().stream().map(id->new LossSequenceModel.Regiment(id,null,null,null,null,null)).toList()));
        return new SelectedUnion(union,selected,missing);
    }
    public static SubjectFrame subjectFrame(ArmyStrengths.Row row,SelectedUnion union){
        List<ArmyStrengths.Regiment> observed=row.regiments() instanceof Present<List<ArmyStrengths.Regiment>> present?present.value():List.of();boolean all=row.regiments() instanceof Present<?>;boolean[] ready={all,all,all,all};int[] counts={0,0,0,0};
        Map<Integer,RaisedRegimentRefresh.Result> refreshes=new LinkedHashMap<>();union.projection().refreshes().forEach(r->refreshes.put(r.regimentId(),r));Map<AssociatedRefillProjection.Key,AssociatedRefillProjection.Chunk> physical=new LinkedHashMap<>();union.projection().chunks().stream().filter(c->c.status()==AssociatedRefillProjection.Status.AVAILABLE).forEach(c->physical.put(c.key(),c));
        List<DerivedStrength> strengths=new ArrayList<>();List<DerivedData> data=new ArrayList<>();List<RegimentGap> missing=new ArrayList<>();
        for(var original:observed){var refresh=refreshes.get(original.armyRegimentId());boolean currentReady=refresh!=null&&refresh.ready();Integer current=currentReady?refresh.current():null,maximum=currentReady?refresh.maximum():null;strengths.add(new DerivedStrength(original,current,maximum));if(!currentReady){all=false;missing.add(new RegimentGap(original.armyRegimentId(),refresh==null?List.of("selected_subject_DATA_refresh"):refresh.missingInputs()));}
            boolean tierKnown=original.composition() instanceof Present<ArmyStrengths.Composition> c&&c.value().siegeTierObservable();Integer tier=original.composition() instanceof Present<ArmyStrengths.Composition> c&&c.value().siegeTier() instanceof Present<Integer> t?t.value():null;
            Boolean eligible=original.supplyEligibility() instanceof Present<ArmyStrengths.SupplyEligibility> e&&e.value().eligible() instanceof Present<Boolean> v?v.value():null;
            for(int flags=0;flags<4;flags++){if((flags&1)!=0&&tierKnown&&tier!=null&&tier>0||(flags&2)!=0&&Boolean.FALSE.equals(eligible))continue;if((flags&1)!=0&&!tierKnown||(flags&2)!=0&&eligible==null||!currentReady)ready[flags]=false;else counts[flags]+=current;}
            FullDataModel.Snapshot snapshot=union.selected().get(original.armyRegimentId());if(snapshot==null)continue;List<DerivedRecord> records=new ArrayList<>();FullDataModel.Coverage status=snapshot.status();String reason=snapshot.unavailableReason();
            for(var record:snapshot.records()){var change=physical.get(new AssociatedRefillProjection.Key(record.persistentRegimentId(),record.chunkIndex()));
                if(change==null){records.add(new DerivedRecord(record,FullDataModel.RecordStatus.UNAVAILABLE,"selected_refill_physical_current_unavailable",null,null,null));if(!Boolean.TRUE.equals(snapshot.nativeLossWriterSkipped())){status=FullDataModel.Coverage.PARTIAL;reason="selected_refill_physical_DATA_partial";}}
                else records.add(new DerivedRecord(record,record.status(),record.unavailableReason(),change.current(),change.maximum(),Integer.valueOf(3).equals(record.stateRaw())&&Integer.valueOf(0).equals(change.current())?change.maximum():change.current()));
            }data.add(new DerivedData(snapshot,status,reason,records));
        }
        List<NativeCount> modeled=new ArrayList<>();for(int flags=0;flags<4;flags++)modeled.add(new NativeCount(flags,ready[flags],ready[flags]?counts[flags]:null));return new SubjectFrame(all,strengths,data,modeled,missing);
    }
    static RateSelection selectRate(LandPost land){
        Boolean branch=null;String source=null;if(land.context().resupply()!=null&&land.context().resupply().nativeLandBranchApplicable()!=null){branch=land.context().resupply().nativeLandBranchApplicable();source="current_land_resupply_v1";}
        else if(land.context().rateInputs()!=null&&land.context().rateInputs().nativeLandBranchApplicable()!=null){branch=land.context().rateInputs().nativeLandBranchApplicable();source="current_land_supply_rate_inputs_v1";}
        if(Boolean.FALSE.equals(branch)){Long rate=land.context().currentObservedTotalRateRaw();return new RateSelection(SupplyMode.FLEET,rate!=null,rate,"observed_current_fleet_rate_fixed_context",source,rate==null?List.of("same_query_current_supply_change_monthly_raw"):List.of());}
        if(Boolean.TRUE.equals(branch))return new RateSelection(SupplyMode.LAND,land.ready(),land.rate(),"conditional_post_refill_land_rate_fixed_context",source,List.of());
        return new RateSelection(SupplyMode.UNKNOWN,false,null,null,null,List.of("same_query_native_land_branch_applicable"));
    }
    public static SelectedMonthly selectedMonthly(ArmyStrengths.Row row,ObjectNode nativeRow,LandPost land){
        if(row.core().status()!=ArmyStrengths.Status.AVAILABLE)return new SelectedMonthly(row,Coverage.UNAVAILABLE,false,null,null,null,null,null,false);
        SelectedUnion union=selectedUnion(row,land.context());SubjectFrame subject=subjectFrame(row,union);RateSelection rate=selectRate(land);ObjectNode frame=derivedRow(nativeRow,subject,rate.raw());
        MonthlyLossModel.Result budgets=MonthlyLossPolicy.constructConditionalMonthlyLossBudgets(MonthlyLossCodec.decodeArmyProjection(frame));LossSequenceModel.Result sequence=budgets.lossSequenceSeed()==null?null:LossSequencePolicy.projectWithDerivedBudgets(LossSequenceCodec.decodeArmyProjection(frame),budgets.lossSequenceSeed());ArmyMonthlyCaller.Result effects=ArmyMonthlyCaller.project(frame,budgets,sequence);
        boolean required=!Boolean.FALSE.equals(budgets.supplyUpdaterAdmitted());boolean complete=budgets.postSupplyReady()&&budgets.conditionalBudgetsReady()&&sequence!=null&&sequence.ready()&&effects.ready();
        boolean any=subject.currentMaximumReady()||rate.ready()||budgets.admissionReady()||budgets.supplyComponent().ready()||budgets.siegeBudgetReady()||budgets.raidBudgetReady();
        return new SelectedMonthly(row,complete?Coverage.AVAILABLE:any?Coverage.PARTIAL:Coverage.UNAVAILABLE,complete,union,subject,land,rate,new MonthlyOutcome(budgets,sequence,effects),required);
    }
    static ObjectNode derivedRow(ObjectNode original,SubjectFrame subject,Long rate){
        ObjectNode row=original.deepCopy();row.putNull("regiment_strengths");ArrayNode strengths=empty().arrayNode();for(DerivedStrength value:subject.regiments()){
            ObjectNode source=ArmyStrengthsCodec.regimentJson(value.source());put(source,"current_soldiers",value.current());put(source,"maximum_soldiers",value.maximum());strengths.add(source);
        }if(subject.currentMaximumReady())row.set("regiment_strengths",strengths);ArrayNode data=row.putArray("regiment_replenishment_records_v1");subject.data().forEach(value->data.add(encodeDerivedData(value)));
        put(row,"current_soldiers",subject.counts().getFirst().count());Integer maximum=subject.currentMaximumReady()?subject.regiments().stream().map(DerivedStrength::maximum).reduce(0,(a,b)->a+b):null;put(row,"maximum_soldiers",maximum);put(row,"current_supply_change_monthly_raw",rate);
        ObjectNode losses=row.get("loss_application_inputs_v1") instanceof ObjectNode existing?existing.deepCopy():empty();for(NativeCount count:subject.counts())put(losses,COUNT_FIELDS.get(count.flags()),count.count());row.set("loss_application_inputs_v1",losses);return row;
    }
    static ObjectNode encodeDerivedData(DerivedData data){ObjectNode row=object(LandContextCodec.encodeData(data.source()));row.put("source","derived_selected_refill_DATA").put("status",data.status().name().toLowerCase(java.util.Locale.ROOT)).put("ready",data.status()==FullDataModel.Coverage.AVAILABLE);put(row,"unavailable_reason",data.unavailableReason());ArrayNode records=object(LandContextCodec.encodeData(data.source())).withArray("records");ArrayNode output=row.putArray("records");for(int index=0;index<data.records().size();index++){DerivedRecord d=data.records().get(index);ObjectNode record=object(records.get(index)).deepCopy().put("status",d.status().name().toLowerCase(java.util.Locale.ROOT));put(record,"unavailable_reason",d.unavailableReason());put(record,"current_soldiers",d.current());put(record,"maximum_soldiers",d.maximum());put(record,"effective_current_soldiers",d.effective());output.add(record);}return row;}
    public static ObjectNode encodeLand(LandPost value){
        ObjectNode out=empty().put("projection_kind","conditional_post_refill_current_province_full_land_supply_rate").put("source_contract_game_version","1.20.0.3").put("input_basis","one_same_query_Strength_row; observed_owner_Province_commander_roster; one_explicit_core_refill_per_observed_persistent_cache").put("army_id",value.armyId()).put("status",wire(value.status())).put("conditional_usage_ready",value.usage().conditionalReady()).put("conditional_full_land_rate_ready",value.ready()).put("scale",100000).put("soldiers_scale",1).put("actual_after",false).put("actual_replenishment",false).put("actual_post_stage_observed",false).put("full_monthly_supply_change_ready",false);put(out,"native_carmy_id",value.nativeCarmyId());put(out,"conditional_supply_usage_soldiers",value.usage().conditionalUsage());put(out,"conditional_post_refill_supply_rate_raw",value.rate());put(out,"current_observed_total_rate_raw",value.context().currentObservedTotalRateRaw());out.set("current_resupply_inputs_v1",LandContextCodec.encodeResupply(value.context().resupply()));out.set("current_land_rate_inputs_v1",LandContextCodec.encodeRate(value.context().rateInputs()));ObjectNode usage=ProvinceUsageProjection.encode(value.usage());out.set("same_input_conditional_province_supply_usage_v1",usage);out.putNull("same_input_conditional_full_land_supply_rate_v1");if(value.fullRate()!=null)out.set("same_input_conditional_full_land_supply_rate_v1",LandContextCodec.encodeProjection(value.fullRate()));ArrayNode missing=out.putArray("missing_inputs");if(!value.usage().conditionalReady()){ObjectNode gap=missing.addObject().put("stage","selected_refill_province_usage");gap.set("inputs",usage.get("missing_inputs"));}else if(!value.ready()){ObjectNode gap=missing.addObject().put("stage","full_land_rate");strings(gap,"inputs",value.fullRate().missingInputs());}return out;
    }
    static ObjectNode encodeSubject(SubjectFrame value){ObjectNode out=empty().put("input_basis","derived_selected_refill_physical_DATA_and_source_current_maximum_refresh").put("current_maximum_ready",value.currentMaximumReady());ArrayNode rows=out.putArray("regiment_strengths");for(DerivedStrength strength:value.regiments()){ObjectNode row=ArmyStrengthsCodec.regimentJson(strength.source());put(row,"current_soldiers",strength.current());put(row,"maximum_soldiers",strength.maximum());rows.add(row);}ArrayNode data=out.putArray("DATA");value.data().forEach(d->data.add(encodeDerivedData(d)));ObjectNode counts=out.putObject("count_by_native_flags"),ready=out.putObject("count_ready_by_native_flags");for(NativeCount count:value.counts()){put(counts,Integer.toString(count.flags()),count.count());ready.put(Integer.toString(count.flags()),count.ready());}ArrayNode missing=out.putArray("missing_inputs");regimentGaps(missing,value.missing());return out;}
    public static ObjectNode encodeMonthly(SelectedMonthly value){
        var row=value.source();ObjectNode out=empty().put("projection_kind","conditional_selected_refill_monthly_supply_assembly").put("source_contract_game_version","1.20.0.3").put("army_id",row.core().army().value()).put("status",wire(value.status())).put("conditional_assembly_ready",value.ready()).put("input_basis","one_selected_core_invocation_per_observed_persistent_cache_in_fixed_captured_context").put("capacity_input_basis","observed_current_capacity_held_in_explicit_fixed_captured_context").put("scale",100000).put("soldiers_scale",1);put(out,"native_carmy_id",nativeId(row));put(out,"observed_supply_stock_raw",supply(row,ArmyStrengths.SupplyKey.CURRENT_SUPPLY));put(out,"observed_supply_capacity_raw",supply(row,ArmyStrengths.SupplyKey.CURRENT_SUPPLY_CAPACITY));put(out,"observed_monthly_rate_raw",supply(row,ArmyStrengths.SupplyKey.CURRENT_SUPPLY_CHANGE_MONTHLY));
        for(String field:List.of("selected_refill_union","derived_subject_frame","joined_post_refill_land_rate","rate_required_by_updater","selected_land_rate_raw","selected_full_supply_rate_raw","selected_full_supply_rate_input_basis","selected_full_supply_rate_branch_source","selected_fleet_rate_raw","conditional_post_stock_raw","monthly_loss_budgets","monthly_caller_effects","actual_post_stage_current","actual_post_supply_usage_soldiers"))out.putNull(field);
        for(String field:List.of("selected_land_rate_ready","selected_full_supply_rate_ready","selected_fleet_rate_ready","conditional_post_stock_ready","conditional_budgets_ready","conditional_loss_sequence_ready","conditional_caller_effects_ready","conditional_physical_refill_ready","conditional_physical_loss_ready","actual_replenishment","actual_loss","actual_effects","full_regular_refill_ready","full_monthly_ready"))out.put(field,false);out.put("selected_full_supply_rate_mode","unknown");ArrayNode premise=out.putArray("captured_context_premise");List.of("owner","current_Province_and_occurrence_order","commander","admission_and_supply_eligibility","loaded_modifiers_and_capacity").forEach(premise::add);ArrayNode missing=out.putArray("missing_inputs");
        if(value.union()==null){missing.add("available_same_query_strength");return out;}
        out.set("selected_refill_union",AssociatedRefillProjection.encode(value.union().projection()));out.set("derived_subject_frame",encodeSubject(value.subject()));out.set("joined_post_refill_land_rate",encodeLand(value.land()));out.put("rate_required_by_updater",value.rateRequired()).put("selected_land_rate_ready",value.land().ready());put(out,"selected_land_rate_raw",value.land().rate());RateSelection rate=value.rate();out.put("selected_full_supply_rate_mode",wire(rate.mode())).put("selected_full_supply_rate_ready",rate.ready());put(out,"selected_full_supply_rate_raw",rate.raw());put(out,"selected_full_supply_rate_input_basis",rate.basis());put(out,"selected_full_supply_rate_branch_source",rate.branchSource());out.put("selected_fleet_rate_ready",rate.mode()==SupplyMode.FLEET&&rate.ready());put(out,"selected_fleet_rate_raw",rate.mode()==SupplyMode.FLEET?rate.raw():null);if(rate.mode()==SupplyMode.FLEET)premise.add("Fleet_association_and_current_game_state_date");
        MonthlyOutcome monthly=value.monthly();out.put("conditional_post_stock_ready",monthly.budgets().postSupplyReady()).put("conditional_budgets_ready",monthly.budgets().conditionalBudgetsReady()).put("conditional_loss_sequence_ready",monthly.sequence()!=null&&monthly.sequence().ready()).put("conditional_caller_effects_ready",monthly.caller().ready()).put("conditional_physical_refill_ready",value.union().projection().chunksReady()).put("conditional_physical_loss_ready",monthly.sequence()!=null&&monthly.sequence().physicalChunksReady());put(out,"conditional_post_stock_raw",monthly.budgets().conditionalPostSupplyRaw());ObjectNode budgets=MonthlyLossCodec.kernelNode(monthly.budgets());budgets.put("input_basis",rate.mode()==SupplyMode.LAND?"derived_selected_refill_current_DATA_counts_and_land_rate; fixed_captured_capacity_and_context":"derived_selected_refill_current_DATA_counts_and_selected_full_supply_rate; fixed_captured_capacity_and_context");budgets.putNull("same_input_conditional_loss_sequence_v1");if(monthly.sequence()!=null){ObjectNode sequence=LossSequenceCodec.sequenceNode(monthly.sequence(),LossSequenceCodec.InputBasis.DERIVED_BUDGET_AND_LOSS_SUBSYSTEM);labelSequence(sequence);budgets.set("same_input_conditional_loss_sequence_v1",sequence);}out.set("monthly_loss_budgets",budgets);ObjectNode caller=ArmyMonthlyCaller.encode(monthly.caller());caller.put("input_basis","derived_selected_refill_budget_and_loss_sequence_with_captured_date_and_counter_cells");out.set("monthly_caller_effects",caller);
        regimentGaps(missing,value.subject().missing());regimentGaps(missing,value.union().missing());if(value.rateRequired()&&!rate.ready()){ObjectNode gap=missing.addObject().put("stage",rate.mode()==SupplyMode.LAND?"selected_full_land_rate":"selected_full_supply_rate");if(rate.mode()==SupplyMode.LAND)gap.set("inputs",encodeLand(value.land()).get("missing_inputs"));else strings(gap,"inputs",rate.missing());}
        if(!monthly.budgets().missingInputs().isEmpty()){ObjectNode gap=missing.addObject().put("stage","stock_and_budgets");strings(gap,"inputs",monthly.budgets().missingInputs());}if(!monthly.caller().missing().isEmpty()){ObjectNode gap=missing.addObject().put("stage","finite_caller_effects");strings(gap,"inputs",monthly.caller().missing());}if(monthly.sequence()!=null&&!monthly.sequence().ready()){ObjectNode gap=missing.addObject().put("stage","derived_four_pass_loss_sequence");gap.set("inputs",LossSequenceCodec.sequenceNode(monthly.sequence()).get("missing_inputs"));}return out;
    }
    static void labelSequence(ObjectNode sequence){sequence.put("input_basis","derived_selected_refill_rate_stock_budget_and_loss_subsystem").put("initial_state_basis","derived_selected_refill_DATA_and_ArRg_current_maximum");if(sequence.get("passes") instanceof ArrayNode passes)for(JsonNode raw:passes){ObjectNode pass=object(raw);pass.put("input_basis","derived_selected_refill_or_prior_writer_stage");if(pass.get("requests") instanceof ArrayNode requests)for(JsonNode request:requests)if(request.get("conditional_chunk_writeback") instanceof ObjectNode writer)writer.put("input_basis","derived_same_stage_DATA_and_explicit_writer_request");}}
    static Long supply(ArmyStrengths.Row row,ArmyStrengths.SupplyKey key){for(var value:row.supply())if(value.key()==key&&value.raw() instanceof Present<Long> raw)return raw.value();return null;}
    static void regimentGaps(ArrayNode array,List<RegimentGap> values){for(RegimentGap value:values){ObjectNode gap=array.addObject().put("army_regiment_id",value.armyRegimentId());strings(gap,"inputs",value.inputs());}}
    static RawJson publicStages(Stage stage,RawJson nativeJson){return ArmyStrengthsRefillBesieging.publicStages(stage,nativeJson);}
    static final List<String> COUNT_FIELDS=List.of("whole_soldiers","definition_le_zero_soldiers","supply_eligible_soldiers","definition_le_zero_supply_eligible_soldiers");
}
